from sqlalchemy.inspection import inspect
from zou.app.utils.fields import serialize_value


class SerializerMixin(object):

    def serialize(self):
        attrs = inspect(self).attrs.keys()
        return {
            "type": self.__class__.__name__.lower(),
            **{attr: serialize_value(getattr(self, attr)) for attr in attrs}
        }

    @staticmethod
    def serialize_list(models):
        return [model.serialize() for model in models]

from typing import Any, Callable

from graphql.type import (
    GraphQLArgument,
    GraphQLField,
    GraphQLInputType,
    GraphQLOutputType,
    GraphQLList,
    GraphQLNonNull,
    GraphQLResolveInfo,
    is_non_null,
)


def plural_identifying_root_field(
    arg_name: str,
    input_type: GraphQLInputType,
    output_type: GraphQLOutputType,
    resolve_single_input: Callable[[GraphQLResolveInfo, str], Any],
    description: str = None,
) -> GraphQLField:
    if is_non_null(input_type):
        input_type = input_type.of_type
    input_args = {
        arg_name: GraphQLArgument(
            GraphQLNonNull(GraphQLList(GraphQLNonNull(input_type)))
        )
    }

    def resolve(_obj, info, **args):
        inputs = args[arg_name]
        return [resolve_single_input(info, input_) for input_ in inputs]

    return GraphQLField(
        GraphQLList(output_type),
        description=description,
        args=input_args,
        resolve=resolve,
    )

